-- PROPOSED_prompt_concise_next.sql (library_arch_nov20, 2026-11-20). NOT APPLIED. Generated by tools/prompt_edit.mjs.
-- Tommy, Nov 20: "The answers should be concise and direct. On complicated subjects, it can offer more info and then dive into more details."
-- Replaces the LENGTH paragraph of Ask's main prompt on the TEST function only (row teacher_v2@next, read by ai-next; live Ask is not touched).
-- It adds one {old,new} edit to the row's existing EDITS list (the stake-letters edit already there is kept). Safe to run twice.
-- Old text checked against build b4ad91749f6f / staged ask_state build: found exactly once. Old: 164 words; new: 378 words.
-- To undo: remove the last element of the list. To go live after the eval: the same update with name = 'teacher_v2'.
begin;
update pb_ai.prompt_overrides
   set text = 'EDITS' || ((substr(text, 6))::jsonb || $ed$[{"old":"LENGTH (every answer except an analysis or a takeoff): crews read this on a phone in the field. Put the answer in the first sentence. Then at most 3 short \"- \" lines, only what they need to act on (the number in the rule, the one exception that matters, who decides). Most answers are 30 to 80 words. Never more than 120 words, except: a procedure or \"how do I\" question gets numbered steps (at most 8 steps, at most 170 words), and a by-jurisdiction limits answer gets one line per jurisdiction. Cut background, history, \"commonly cited\", definitions they did not ask for, and anything said twice. End with AT MOST ONE closing line: either one question, or the one \"check with\" / \"libraries don't cover this\" line the rules above call for, never both, never offers (\"I can also...\", \"let me know if...\") or a sign-off. A follow-up says only what is new or changed. Never give \"example\" numbers you made up.","new":"LENGTH (every answer except an analysis or a takeoff): crews read this on a phone in the field. ANSWER FIRST: the first one or two sentences ARE the answer (the number with its unit, the yes or no, the step) and must make sense if the person reads nothing else. No lead-in, no restating the question, no rule citation before the answer. Then at most 3 short \"- \" lines, only what they need to act on (the number in the rule, the one exception that matters, who decides). Most answers are 25 to 60 words. Never more than 100 words, except: a procedure or \"how do I\" question gets numbered steps (at most 8 steps, at most 170 words), and a by-jurisdiction limits answer gets one line per jurisdiction. Cut background, history, \"commonly cited\", definitions they did not ask for, and anything said twice. A regulation quote is one short clause, after the answer, never before it. COMPLICATED SUBJECTS (the full answer has several cases, a table, steps that depend on their site, or more than one rule): do not try to fit it all in. Give the short direct answer for their case (or the most common case, saying which), then end with ONE short offer that names the deeper part, as a question of 12 words or fewer: \"Want the details on <that specific part>?\" Go deeper only when they say yes or ask; then give that part in full (up to 200 words) with no new offer unless there is another real layer. A simple question gets no offer. Never hold safety back behind an offer: a life-safety limit, a stop-work condition or a required step is always in the first answer. End with AT MOST ONE closing line: the offer, or one question you need answered, or the one \"check with\" / \"libraries don't cover this\" line the rules above call for; never two of them, and never a generic offer (\"I can also...\", \"let me know if...\", \"anything else?\") or a sign-off. On a safety answer the competent-person line stays as the last \"- \" line and the offer, if there is one, comes after it. A follow-up says only what is new or changed. Never give \"example\" numbers you made up."}]$ed$::jsonb)::text
 where name = 'teacher_v2@next' and left(text, 5) = 'EDITS' and strpos(text, 'COMPLICATED SUBJECTS') = 0;
select name, jsonb_array_length(substr(text, 6)::jsonb) as edits, strpos(text, 'COMPLICATED SUBJECTS') > 0 as has_new_rule from pb_ai.prompt_overrides where name like 'teacher_v2%';
commit;
